#!/usr/bin/env bash
# Some portions generated by Codex. Separate diagnostic JVMs, never clean timing evidence.
set -euo pipefail
cd "$(dirname "$0")/../.."
: "${CP_A:?}" "${CP_B:?}" "${LOCK:?}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
JFR=${JFR:-../toolchain/jdk-25.0.5+8/bin/jfr}
OUT=${OUT:-experiments/threadlocal-audit/profiles-01}
mkdir -p "$OUT/harness"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_B" -d "$OUT/harness" experiments/threadlocal-audit/ThreadLocal{Query,CoScan}Benchmark.java
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640)
for regime in regular interpreted janino coscan; do
 for variant in A B; do
  cp=$CP_A; [[ $variant == B ]] && cp=$CP_B
  file="$(realpath "$OUT")/$regime-$variant"
  if [[ $regime == coscan ]]; then
   "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}" -Daudit.warmups=20 -Daudit.jfr="$file.jfr" \
    -cp "$OUT/harness:$cp" org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalCoScanBenchmark 1000 30 > "$file.log" 2>&1
  else
   "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}" -Daudit.regime="$regime" \
    -Doverlay.benchmark.warmups=20 -Daudit.jfr="$file.jfr" -cp "$OUT/harness:$cp" \
    org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalQueryBenchmark 100 10 5 true > "$file.log" 2>&1
  fi
  "$JFR" print --json --events jdk.ExecutionSample,jdk.NativeMethodSample "$file.jfr" > "$file.samples.json"
 done
done
python3 experiments/threadlocal-audit/summarize-profiles.py "$OUT" > "$OUT/summary.json"
